package license

import "encoding/hex"

// MasterPublicKey is the ML-DSA-65 public key for the KHEPRA license signing
// root. Generated via cmd/root-ceremony (fingerprint KHEPRA-ROOT-ebe9dd80653e6d66);
// the corresponding private key exists only as Shamir shards (3-of-5, see
// keys/root-ceremony/ — gitignored, not committed). ParseMCPLicense pins
// VerifySovereignLicense against this constant instead of trusting whatever
// SignerPublicKey a license happens to carry — without this, any self-signed
// KhepraLicense JSON verifies against itself.
var MasterPublicKey = mustDecodeHex(
	"")

func mustDecodeHex(s string) []byte {
	b, err := hex.DecodeString(s)
	if err != nil {
		panic("license: invalid MasterPublicKey hex: " + err.Error())
	}
	return b
}
